import { describe, expect, it } from 'vitest';
import { hasGeneratorAnnotation, hasGeneratorHeader, headerLines } from './generator-marker.mjs';

describe('the header a known code generator writes', () => {
  it.each([
    '# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n',
    '# Generated by the gRPC Python protocol compiler plugin. DO NOT EDIT!\n"""Client."""\n',
    '# generated by datamodel-codegen:\n#   filename:  api.yaml\n',
    '# coding: utf-8\n\n"""\n    Petstore\n\n    The version: 1.0.0\n    Generated by OpenAPI Generator (https://openapi-generator.tech)\n"""\n',
    '/* tslint:disable */\n/**\n * Petstore\n *\n * NOTE: This class is auto generated by OpenAPI Generator (https://openapi-generator.tech).\n */\n',
    '// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\n',
    '// @generated by protoc-gen-es v1.10.0 with parameter "target=ts"\n',
    '#\n# Autogenerated by Thrift Compiler (0.20.0)\n#\n',
    '/*\n * This file is generated by jOOQ.\n */\npackage db;\n',
    '// Code generated by Wire protocol buffer compiler, do not edit.\n// Source: shop.Order\npackage shop\n',
    '/**\n * Autogenerated by Avro\n *\n * DO NOT EDIT DIRECTLY\n */\npackage shop;\n',
    '// Generated from Shop.g4 by ANTLR 4.13.1\npackage shop;\n',
    '//\n// This file was generated by the Eclipse Implementation of JAXB, v3.0.2\n//\npackage shop;\n',
    '/** NOTE: This class is auto generated by the swagger code generator program (https://github.com/swagger-api/swagger-codegen.git). */\npackage api;\n',
    '/* AUTO-GENERATED FILE.  DO NOT MODIFY.\n *\n * This class was automatically generated by the aapt tool. */\npackage app;\n',
  ])('is found in the leading comments or the module docstring: %j', (text) => {
    expect(hasGeneratorHeader(text)).toBe(true);
  });

  it.each([
    '"""Builds the auto-generated invoice numbers."""\n',
    '# DO NOT EDIT\n',
    '// @generated\n',
    '# Generated by Django 5.1 on 2026-01-01 10:00\n',
    'import os\n# generated by datamodel-codegen:\n',
    '"""Models."""\n"""Generated by OpenAPI Generator (https://openapi-generator.tech)"""\n',
    '// This file is generated by hand.\npackage shop;\n',
    'package shop;\n// This file is generated by jOOQ.\n',
  ])('is not a generic marker, a hand-edited migration or text below the header: %j', (text) => {
    expect(hasGeneratorHeader(text)).toBe(false);
  });

  it('reads the comment and docstring lines without their syntax', () => {
    expect(
      headerLines('#!/usr/bin/env python\n/* a\n * b */\nr"""c\nd"""  # e\nx = 1\n# f\n'),
    ).toEqual(['/usr/bin/env python', 'a', 'b', 'c', 'd']);
  });
});

describe('the annotation a known annotation processor writes', () => {
  it.each([
    '@Generated("org.mapstruct.ap.MappingProcessor")\npublic class OrderMapperImpl {}\n',
    '@javax.annotation.processing.Generated(value = "org.mapstruct.ap.MappingProcessor", date = "2026")\nclass A {}\n',
    '@jakarta.annotation.Generated(value = {"dagger.internal.codegen.ComponentProcessor"})\nclass A {}\n',
    '@javax.annotation.Generated(value = "by gRPC proto compiler (version 1.60.0)", comments = "Source: shop.proto")\npublic final class ShopGrpc {}\n',
  ])('is found: %j', (text) => {
    expect(hasGeneratorAnnotation(text)).toBe(true);
  });

  it.each([
    '@Generated\nclass A {}\n',
    '@Generated("hand-written")\nclass A {}\n',
    '// @Generated("org.mapstruct.ap.MappingProcessor")\nclass A {}\n',
    'class A { String s = "@Generated(org.mapstruct.ap.MappingProcessor)"; }\n',
  ])('is not taken without a known processor or inside a comment or string: %j', (text) => {
    expect(hasGeneratorAnnotation(text)).toBe(false);
  });
});
